documents.counted:
yamaa: "1.0"
type: spec
domain: TEST
keys: [SUBJ, SEQ, DOSE]
input:
  EX: {path: ex.csv, types: {SEQ: int, CNT: int}}
output: {path: out.csv, columns: [SUBJ, SEQ, DOSE]}
intermediates:
  - id: ADMIN
    dataset: EX
    repeat: {count: EX.CNT, index: N}
    derivations:
      SUBJ: {type: str, derivation: EX.SUBJ}
      SEQ: {type: int, derivation: EX.SEQ}
      DOSE: N
columns:
  - {name: SUBJ, type: str}
  - {name: SEQ, type: int}
  - {name: DOSE, type: int}
rows:
  - id: each
    dataset: ADMIN
    derivations: {SUBJ: ADMIN.SUBJ, SEQ: ADMIN.SEQ, DOSE: ADMIN.DOSE}

documents.kept:
yamaa: "1.0"
type: spec
domain: TEST
keys: [SUBJ, SEQ, DOSE]
input:
  EX: {path: ex.csv, types: {SEQ: int, CNT: int}}
output: {path: out.csv, columns: [SUBJ, SEQ, DOSE]}
intermediates:
  - id: KEPT
    dataset: EX
    filter: "EX.SUBJ <> 'A'"
  - id: ADMIN
    dataset: KEPT
    repeat: {count: KEPT.CNT, index: N}
    derivations:
      SUBJ: {type: str, derivation: KEPT.SUBJ}
      SEQ: {type: int, derivation: KEPT.SEQ}
      DOSE: N
columns:
  - {name: SUBJ, type: str}
  - {name: SEQ, type: int}
  - {name: DOSE, type: int}
rows:
  - id: each
    dataset: ADMIN
    derivations: {SUBJ: ADMIN.SUBJ, SEQ: ADMIN.SEQ, DOSE: ADMIN.DOSE}

documents.lookup:
yamaa: "1.0"
type: spec
domain: TEST
keys: [SUBJ]
input:
  DM: dm.csv
  EX: {path: ex.csv, types: {SEQ: int, CNT: int}}
base: DM
output: {path: out.csv, columns: [SUBJ, VALUE]}
intermediates:
  - id: ADMIN
    dataset: EX
    repeat: {count: EX.CNT, index: N}
    derivations:
      SUBJ: {type: str, derivation: EX.SUBJ}
      SEQ: {type: int, derivation: EX.SEQ}
      DOSE: N
  - id: FINAL
    dataset: ADMIN
    key: {SUBJ: DM.SUBJ}
    order_by: [ADMIN.SEQ, ADMIN.DOSE]
    keep: last
columns:
  - {name: SUBJ, type: str, derivation: DM.SUBJ}
  - {name: VALUE, type: int, derivation: FINAL.DOSE}

documents.aggregate:
yamaa: "1.0"
type: spec
domain: TEST
keys: [SUBJ]
input:
  DM: dm.csv
  EX: {path: ex.csv, types: {SEQ: int, CNT: int}}
base: DM
output: {path: out.csv, columns: [SUBJ, VALUE]}
intermediates:
  - id: ADMIN
    dataset: EX
    repeat: {count: EX.CNT, index: N}
    derivations:
      SUBJ: {type: str, derivation: EX.SUBJ}
      SEQ: {type: int, derivation: EX.SEQ}
      DOSE: N
columns:
  - {name: SUBJ, type: str, derivation: DM.SUBJ}
  - name: VALUE
    type: int
    derivation:
      aggregate: {expr: "COUNT(ADMIN.*)", key: {SUBJ: DM.SUBJ}}

edits.to:
repeat:
  count: {diff: {type: date, start: EX.START, end: EX.END, unit: day, closed: both}}
  index: N

repeat: {count: EX.CNT, index: N}
verifications:
  - unique: [SUBJ, SEQ]
